<?php
namespace App\Http\Requests\Crm;
use Illuminate\Foundation\Http\FormRequest;
class ClientRequest extends FormRequest { public function authorize():bool{return $this->user()->can('clients.create')||$this->user()->can('clients.edit');} public function rules():array{return ['company_name'=>['required','string','max:255'],'contact_person'=>['nullable','string','max:255'],'phone'=>['nullable','string','max:50'],'email'=>['nullable','email','max:255'],'website'=>['nullable','url','max:255'],'address'=>['nullable','string','max:2000'],'city'=>['nullable','string','max:100'],'country'=>['nullable','string','max:100'],'industry'=>['nullable','string','max:100'],'client_type'=>['nullable','string','max:100'],'account_manager_id'=>['nullable','exists:users,id'],'status'=>['required','in:active,inactive,prospect'],'notes'=>['nullable','string','max:5000']];} }
